import{G as e,W as t,n,rt as r}from"./chunks/framework.CzKPlK1V.js";var i=JSON.parse(`{"title":"Group Management Guide","description":"","frontmatter":{},"headers":[],"relativePath":"02-consumer/08-group.md","filePath":"02-consumer/08-group.md"}`),a={name:`02-consumer/08-group.md`};function o(n,i,a,o,s,c){return r(),t(`div`,null,[...i[0]||=[e(`<h1 id="group-management-guide" tabindex="-1">Group Management Guide <a class="header-anchor" href="#group-management-guide" aria-label="Permalink to “Group Management Guide”">​</a></h1><h2 id="page-introduction" tabindex="-1">Page Introduction <a class="header-anchor" href="#page-introduction" aria-label="Permalink to “Page Introduction”">​</a></h2><p>Groups are used to categorize and organize site posts. Each group can have a name, subtitle, description, image, and settings related to its display and SEO. You can also create a parent-child hierarchy.</p><p>The group editing page lets you manage the group&#39;s information, configure its appearance in supported areas of the theme, and, if needed, define Schema Markup for related posts or for the group page itself.</p><p>Figure 1 - The group editing page (Edit group) and its numbered sections.</p><h2 id="_1-general-group-information" tabindex="-1">1. General Group Information <a class="header-anchor" href="#_1-general-group-information" aria-label="Permalink to “1. General Group Information”">​</a></h2><p>This section is used to manage the group&#39;s basic information.</p><table tabindex="0"><thead><tr><th>Field</th><th>Purpose</th></tr></thead><tbody><tr><td>Group name</td><td>Specifies the group name.</td></tr><tr><td>Group slug</td><td>The text identifier used in the group&#39;s URL. According to the panel&#39;s guidance, if this field is empty, its value is generated automatically.</td></tr><tr><td>Subtitle</td><td>Specifies the group&#39;s subtitle.</td></tr><tr><td>Group Parent</td><td>Selects the parent group to create a hierarchical structure. If there is no parent, select <code>No parent</code>.</td></tr><tr><td>Hide in menu</td><td>Specifies whether the group should be hidden in menus that display subgroups. This option alone does not mean that the group page is disabled.</td></tr><tr><td>Description</td><td>Stores the group&#39;s description. This field uses a text editor for writing and formatting content.</td></tr></tbody></table><p>The group name, subtitle, and description support multilingual content.</p><p>Note: To place a group under another group, select the appropriate value in the <code>Group Parent</code> field. If it is a top-level group, you can leave it without a parent.</p><h2 id="_2-feature-image" tabindex="-1">2. Feature Image <a class="header-anchor" href="#_2-feature-image" aria-label="Permalink to “2. Feature Image”">​</a></h2><p>This section is used to select the group&#39;s main image. The feature image may appear in lists or in site areas where the theme uses an image to display a group.</p><p>Use the file upload option in this section to select an image.</p><h2 id="_3-background-image" tabindex="-1">3. Background Image <a class="header-anchor" href="#_3-background-image" aria-label="Permalink to “3. Background Image”">​</a></h2><p>In this section, you can select the group&#39;s background image. Some themes and design layouts can use this image.</p><p>Whether the background image is displayed depends on whether the theme supports this feature. Selecting an image therefore does not necessarily mean it will appear on every page or in every area of the site.</p><h2 id="_4-attachments" tabindex="-1">4. Attachments <a class="header-anchor" href="#_4-attachments" aria-label="Permalink to “4. Attachments”">​</a></h2><p>This section is used to manage attachments related to the group.</p><p>Use the add attachment button to start adding an attachment. The number next to the button indicates how many attachments are displayed in this section.</p><p>The types of attachments available and how they are displayed depend on the panel&#39;s attachment features.</p><h2 id="_5-canonical-url" tabindex="-1">5. Canonical URL <a class="header-anchor" href="#_5-canonical-url" aria-label="Permalink to “5. Canonical URL”">​</a></h2><p>The <code>Canonical</code> field is used to enter the canonical URL of the group page in the SEO settings.</p><p>This URL helps search engines identify the canonical version of the page, especially when similar pages or different URLs contain the same content.</p><p>Note: The URL you enter should match the page you intend to designate as the canonical version.</p><h2 id="_6-configuring-a-custom-group-theme" tabindex="-1">6. Configuring a Custom Group Theme <a class="header-anchor" href="#_6-configuring-a-custom-group-theme" aria-label="Permalink to “6. Configuring a Custom Group Theme”">​</a></h2><p>The gray button next to the page title, marked with a color palette icon, provides access to the custom theme settings for the group.</p><p>This feature is used to customize the group&#39;s appearance and may allow it to look different from the site&#39;s general theme.</p><p>These settings apply only to this group. The available options and how each setting is applied depend on the theme settings page&#39;s features.</p><h2 id="schema-markup" tabindex="-1">Schema Markup <a class="header-anchor" href="#schema-markup" aria-label="Permalink to “Schema Markup”">​</a></h2><p>The group editing page has two Schema Markup editors, each with a separate purpose:</p><h3 id="schema-markup-for-posts-in-this-group" tabindex="-1">Schema Markup for Posts in This Group <a class="header-anchor" href="#schema-markup-for-posts-in-this-group" aria-label="Permalink to “Schema Markup for Posts in This Group”">​</a></h3><p>The first editor, titled <code>Markup schema for posts of this group</code>, is used to define the default Schema Markup for posts related to the group, if the application logic uses this setting.</p><h3 id="schema-markup-for-the-group-page" tabindex="-1">Schema Markup for the Group Page <a class="header-anchor" href="#schema-markup-for-the-group-page" aria-label="Permalink to “Schema Markup for the Group Page”">​</a></h3><p>The second editor, titled <code>Markup schema</code>, is used to define the Schema Markup for the group page itself.</p><p>Both sections allow you to enter Schema code and use replaceable variables. You can also add multiple schemas to one editor.</p><p>For information about inserting variables, using the buttons above the editor, selecting a Syntax, and how the Reset button works, see the documentation on using the Schema Markup editor.</p><h2 id="saving-changes" tabindex="-1">Saving Changes <a class="header-anchor" href="#saving-changes" aria-label="Permalink to “Saving Changes”">​</a></h2><p>After completing the information and configuring the required sections, click the Save button at the bottom of the page.</p><p>Before saving, it is a good idea to check the group name and URL, parent group, images, Canonical URL, and Schema Markup settings to make sure they match your intended configuration.</p>`,39)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};